              "dir": "ltr",
              "code": "static int sod(int m, int d)\n{\n  d++;\n  if ((m == 1 || m == 3 || m == 5 || m == 7 || m == 8 || m == 10 || m == 12) && d > 31)\n  {\n     d = 1;\n     m++;\n  }\n  else if ((m == 4 || m == 6 || m == 9 || m == 11) && d > 30)\n  {\n     d = 1;\n     m++;\n  }\n  else if (m == 2 && d > 28)\n  {\n     d = 1;\n     m++;\n  }\n  if (m > 12)\n      m = 1;\n  return m * 100 + d;\n}\n static void Main(string[] args)\n {\n    int result = sod(11, 31);\n    Console.WriteLine(result);\n        }"
